// The Marketing pack's tables (docs/marketing-plan.md §4.3; ARCHITECTURE §12.0 "Marketing"): a
// client's measured websites and what their visitors did. Same tenancy rules as the platform's
// (CLAUDE.md invariant 1): every table has tenant_id, forced RLS on app.tenant_ids, and composite
// foreign keys (site_id, tenant_id) so a row can only point at the same client's site.
//
// Migration 0037 (docs/plan.md §1.72) creates the measurement tables and 0038 (§1.73) the rest of
// the area's (search, content, claims, reports, the forum watch): generated by drizzle-kit from
// this file, which the db package's drizzle config lists, plus hand-written SQL for the grants,
// RLS, insert-only triggers and the pack-ownership comments. This file imports only drizzle-orm and the platform's schema at
// runtime, so drizzle-kit can load it.
//
// Never stored, anywhere: an IP address, a user agent string, a cookie, or any identifier that
// outlives a UTC day (the salt is deleted when its day is over). A visit's times are kept to the
// hour, and a visit that reached a goal says so with no link to who the visitor is.

import { agentVersion, appUser, connection, externalAction, run, tenant } from "@countersign/db";
import { type SQL, sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  bigint,
  boolean,
  check,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  type PgTableExtraConfigValue,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import { BOT_REASONS, DEVICE_CLASSES, EVENT_KINDS, SOURCE_GROUPS } from "./measure/events";

export const SITE_STATUSES = ["on", "off"] as const;
export type SiteStatus = (typeof SITE_STATUSES)[number];

/** The dimensions a day's visit totals are kept by; `all` has the empty key. */
export const TOTAL_DIMENSIONS = ["all", "source", "country", "device", "entry"] as const;
export type TotalDimension = (typeof TOTAL_DIMENSIONS)[number];

/** Engaged-time bands in seconds, the last open-ended: [<10, 10–30, 30–60, 60–120, 120–240, ≥240]. */
export const ENGAGED_BAND_UPPER_SECONDS = [10, 30, 60, 120, 240] as const;
export const ENGAGED_BANDS = ENGAGED_BAND_UPPER_SECONDS.length + 1;
/** A bounce: one page, no tracked click, no goal, and less than this engaged. */
export const BOUNCE_ENGAGED_MS = 10_000;
// DECISION (Plenary Labs' retention, owner 2026-10-25, kept for Mezonas): raw events 90 days,
// visits 13 months, daily totals for good (they say nothing about any one visitor).
export const SITE_EVENT_RETENTION_DAYS = 90;
export const SITE_VISIT_RETENTION_MONTHS = 13;
/** A visit's page list is cut here: a visit that reads more is not a person reading. */
export const SITE_VISIT_MAX_PAGES = 50;
/** Events one visit may send in a day before the rest are counted as `rate` and dropped. */
export const SITE_VISIT_MAX_EVENTS = 500;

function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.raw(values.map((v) => `'${v}'`).join(", "))})`;
}

const tenantId = () =>
  uuid("tenant_id")
    .notNull()
    .references(() => tenant.id);
const siteId = () => uuid("site_id").notNull();
const day = () => date("day").notNull();
const ts = (name: string) => timestamp(name, { withTimezone: true });
/** Every row of a site's data points at the same client's site. */
const siteFk = (name: string, t: { siteId: AnyPgColumn; tenantId: AnyPgColumn }) =>
  foreignKey({
    name,
    columns: [t.siteId, t.tenantId],
    foreignColumns: [site.id, site.tenantId],
  });
const pathCheck = (name: string, column: AnyPgColumn) =>
  check(name, sql`left(${column}, 1) = '/' and length(${column}) <= 512`);

/**
 * A website a client has measured: its domain (lower case, without `www.`), and the tracked
 * elements (`data-track` names) whose click counts as the visit's goal, e.g. "Talk to us".
 */
export const site = pgTable(
  "site",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    domain: text("domain").notNull(),
    name: text("name").notNull(),
    goals: text("goals").array().notNull().default(sql`'{}'::text[]`),
    status: text("status").$type<SiteStatus>().notNull().default("on"),
    createdByUserId: uuid("created_by_user_id").references(() => appUser.id),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [
    unique("site_id_tenant_key").on(t.id, t.tenantId),
    unique("site_domain_key").on(t.tenantId, t.domain),
    check("site_status_check", oneOf(t.status, SITE_STATUSES)),
    check(
      "site_domain_check",
      sql`${t.domain} ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' and ${t.domain} !~ '^www\\.'`,
    ),
    check("site_goals_check", sql`cardinality(${t.goals}) <= 20`),
  ],
);

/** The day's random salt for a site's visit hash. Deleted once its day is over. */
export const siteSalt = pgTable(
  "site_salt",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    salt: text("salt").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day] }),
    siteFk("site_salt_site_fk", t),
    check("site_salt_hex", sql`${t.salt} ~ '^[0-9a-f]{64}$'`),
  ],
);

/** One thing a page reported. Raw; kept 90 days. */
export const siteEvent = pgTable(
  "site_event",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    siteId: siteId(),
    at: ts("at").notNull(),
    day: day(),
    visit: text("visit").notNull(),
    viewId: uuid("view_id").notNull(),
    kind: text("kind").notNull(),
    path: text("path").notNull(),
    referrerHost: text("referrer_host"),
    referrerPath: text("referrer_path"),
    utmSource: text("utm_source"),
    utmMedium: text("utm_medium"),
    utmCampaign: text("utm_campaign"),
    utmContent: text("utm_content"),
    sourceGroup: text("source_group"),
    sourceName: text("source_name"),
    country: text("country"),
    region: text("region"),
    city: text("city"),
    timeZone: text("time_zone"),
    device: text("device"),
    browser: text("browser"),
    os: text("os"),
    language: text("language"),
    engagedMs: integer("engaged_ms"),
    scroll: integer("scroll"),
    target: text("target"),
    position: integer("position"),
    form: text("form"),
  },
  (t) => [
    siteFk("site_event_site_fk", t),
    check("site_event_kind", oneOf(t.kind, EVENT_KINDS)),
    pathCheck("site_event_path", t.path),
    check("site_event_visit_hex", sql`${t.visit} ~ '^[0-9a-f]{32}$'`),
    check(
      "site_event_source_group",
      sql`${t.sourceGroup} is null or ${oneOf(t.sourceGroup, SOURCE_GROUPS)}`,
    ),
    check("site_event_device", sql`${t.device} is null or ${oneOf(t.device, DEVICE_CLASSES)}`),
    check("site_event_country", sql`${t.country} is null or ${t.country} ~ '^[A-Z]{2}$'`),
    check(
      "site_event_ranges",
      sql`(${t.engagedMs} is null or ${t.engagedMs} between 0 and 3600000)
        and (${t.scroll} is null or ${t.scroll} between 0 and 4)
        and (${t.position} is null or ${t.position} between 0 and 100)`,
    ),
    check(
      "site_event_kind_fields",
      sql`case ${t.kind}
        when 'view' then ${t.sourceGroup} is not null and ${t.device} is not null
        when 'engage' then ${t.engagedMs} is not null and ${t.scroll} is not null
        when 'click' then ${t.target} is not null and ${t.position} is not null
        when 'form_seen' then ${t.form} is not null
        else false end`,
    ),
    index("site_event_visit_idx").on(t.tenantId, t.siteId, t.day, t.visit),
  ],
);

/** One visit (one browser, one UTC day), built nightly from its events. Kept 13 months. */
export const siteVisit = pgTable(
  "site_visit",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    visit: text("visit").notNull(),
    /** To the hour: enough for the hours of the week, too coarse to set beside anything else. */
    startedAt: ts("started_at").notNull(),
    endedAt: ts("ended_at").notNull(),
    entryPath: text("entry_path").notNull(),
    exitPath: text("exit_path").notNull(),
    pages: text("pages").array().notNull(),
    views: integer("views").notNull(),
    clicks: integer("clicks").notNull(),
    engagedMs: integer("engaged_ms").notNull(),
    sourceGroup: text("source_group").notNull(),
    sourceName: text("source_name"),
    referrerHost: text("referrer_host"),
    utmSource: text("utm_source"),
    utmMedium: text("utm_medium"),
    utmCampaign: text("utm_campaign"),
    utmContent: text("utm_content"),
    country: text("country"),
    region: text("region"),
    city: text("city"),
    timeZone: text("time_zone"),
    device: text("device").notNull(),
    browser: text("browser"),
    os: text("os"),
    language: text("language"),
    sawForm: boolean("saw_form").notNull(),
    /** A click on one of the site's goals (e.g. "Talk to us"); `goal` is the first one's name. */
    reachedGoal: boolean("reached_goal").notNull(),
    goal: text("goal"),
    bounced: boolean("bounced").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.visit] }),
    siteFk("site_visit_site_fk", t),
    check(
      "site_visit_hours",
      sql`date_trunc('hour', ${t.startedAt}, 'UTC') = ${t.startedAt}
      and date_trunc('hour', ${t.endedAt}, 'UTC') = ${t.endedAt}`,
    ),
    check("site_visit_goal", sql`${t.reachedGoal} = (${t.goal} is not null)`),
    index("site_visit_tenant_idx").on(t.tenantId, t.siteId, t.day),
  ],
);

/** Each page's day: views, entries, exits, goals, engaged time and how far down readers got. */
export const siteDailyPage = pgTable(
  "site_daily_page",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    path: text("path").notNull(),
    views: integer("views").notNull(),
    entries: integer("entries").notNull(),
    exits: integer("exits").notNull(),
    /** Visits that entered here and reached a goal. */
    goals: integer("goals").notNull(),
    formSeen: integer("form_seen").notNull(),
    engagedMs: bigint("engaged_ms", { mode: "number" }).notNull(),
    engagedBands: integer("engaged_bands").array().notNull(),
    /** Views that reached each quarter of the page: [25%, 50%, 75%, 100%]. */
    scrollReached: integer("scroll_reached").array().notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.path] }),
    siteFk("site_daily_page_site_fk", t),
    pathCheck("site_daily_page_path", t.path),
    check(
      "site_daily_page_arrays",
      sql`cardinality(${t.engagedBands}) = ${sql.raw(String(ENGAGED_BANDS))} and cardinality(${t.scrollReached}) = 4`,
    ),
  ],
);

/** Each tracked element's day: clicks, and the median position on the page (% of its height). */
export const siteDailyClick = pgTable(
  "site_daily_click",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    path: text("path").notNull(),
    target: text("target").notNull(),
    clicks: integer("clicks").notNull(),
    position: integer("position").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.path, t.target] }),
    siteFk("site_daily_click_site_fk", t),
    pathCheck("site_daily_click_path", t.path),
    check("site_daily_click_counts", sql`${t.clicks} >= 1 and ${t.position} between 0 and 100`),
  ],
);

/** A day's visit totals, overall and by one dimension at a time. */
export const siteDailyTotal = pgTable(
  "site_daily_total",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    dimension: text("dimension").$type<TotalDimension>().notNull(),
    key: text("key").notNull(),
    visits: integer("visits").notNull(),
    views: integer("views").notNull(),
    goals: integer("goals").notNull(),
    bounces: integer("bounces").notNull(),
    engagedMs: bigint("engaged_ms", { mode: "number" }).notNull(),
    engagedBands: integer("engaged_bands").array().notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.dimension, t.key] }),
    siteFk("site_daily_total_site_fk", t),
    check("site_daily_total_dimension", oneOf(t.dimension, TOTAL_DIMENSIONS)),
    check(
      "site_daily_total_key",
      sql`(${t.dimension} = 'all') = (${t.key} = '') and length(${t.key}) <= 512`,
    ),
    check(
      "site_daily_total_bands",
      sql`cardinality(${t.engagedBands}) = ${sql.raw(String(ENGAGED_BANDS))}`,
    ),
  ],
);

/** Requests not counted as visits, per day and reason. */
export const siteBotDaily = pgTable(
  "site_bot_daily",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    day: day(),
    reason: text("reason").notNull(),
    requests: integer("requests").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.day, t.reason] }),
    siteFk("site_bot_daily_site_fk", t),
    check("site_bot_daily_reason", oneOf(t.reason, BOT_REASONS)),
    check("site_bot_daily_requests", sql`${t.requests} >= 0`),
  ],
);

// ---------------------------------------------------------------------------------------------
// Migration 0038 (docs/plan.md §1.73): search, content, claims, reports and the forum watch.
// ---------------------------------------------------------------------------------------------

export const SEARCH_PROVIDERS = ["google", "bing"] as const;
export type SearchProvider = (typeof SEARCH_PROVIDERS)[number];
export const CONTENT_KINDS = ["guide"] as const;
export type ContentKind = (typeof CONTENT_KINDS)[number];
export const CONTENT_STATUSES = ["draft", "published", "unpublished"] as const;
export type ContentStatus = (typeof CONTENT_STATUSES)[number];
export const PUBLISH_ACTIONS = ["publish", "unpublish"] as const;
export type PublishAction = (typeof PUBLISH_ACTIONS)[number];
export const REPORT_KINDS = ["weekly"] as const;
export type ReportKind = (typeof REPORT_KINDS)[number];
export const REPORT_ACTION_DECISIONS = ["open", "done", "not_now"] as const;
export type ReportActionDecision = (typeof REPORT_ACTION_DECISIONS)[number];
export const FORUM_SOURCES = ["hackernews", "pasted"] as const;
export type ForumSource = (typeof FORUM_SOURCES)[number];
export const FORUM_OUTCOMES = ["drafted", "passed"] as const;
export type ForumOutcome = (typeof FORUM_OUTCOMES)[number];
export const FORUM_REPLY_STATUSES = ["waiting", "approved", "rejected", "posted"] as const;
export type ForumReplyStatus = (typeof FORUM_REPLY_STATUSES)[number];

/** Only the same client's agent version (a template's test copy in a client is the client's). */
const agentVersionFk = (name: string, t: { agentVersionId: AnyPgColumn; tenantId: AnyPgColumn }) =>
  foreignKey({
    name,
    columns: [t.agentVersionId, t.tenantId],
    foreignColumns: [agentVersion.id, agentVersion.tenantId],
  });
const runFk = (name: string, t: { runId: AnyPgColumn; tenantId: AnyPgColumn }) =>
  foreignKey({ name, columns: [t.runId, t.tenantId], foreignColumns: [run.id, run.tenantId] });

/**
 * Where a site's search figures come from: one per client, site and provider. Its state is ours
 * (how far the data runs, when it was last imported, the last failure in our words, never the
 * provider's body); the connection holds the key.
 */
export const searchSource = pgTable(
  "search_source",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    siteId: siteId(),
    provider: text("provider").$type<SearchProvider>().notNull(),
    connectionId: uuid("connection_id"),
    /** The last day the provider's final data covers. */
    dataRunsTo: date("data_runs_to"),
    lastImportedAt: ts("last_imported_at"),
    lastError: text("last_error"),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [
    unique("search_source_id_tenant_key").on(t.id, t.tenantId),
    unique("search_source_site_provider_key").on(t.tenantId, t.siteId, t.provider),
    siteFk("search_source_site_fk", t),
    foreignKey({
      name: "search_source_connection_fk",
      columns: [t.connectionId, t.tenantId],
      foreignColumns: [connection.id, connection.tenantId],
    }),
    check("search_source_provider", oneOf(t.provider, SEARCH_PROVIDERS)),
    check("search_source_error", sql`${t.lastError} is null or length(${t.lastError}) <= 500`),
  ],
);

const searchCounts = (
  name: string,
  t: { impressions: AnyPgColumn; clicks: AnyPgColumn; position: AnyPgColumn },
) =>
  check(
    name,
    sql`${t.impressions} >= 0 and ${t.clicks} >= 0 and (${t.position} is null or ${t.position} >= 0)`,
  );

/** A day's search figures by query and page. The import deletes and inserts a day whole. */
export const searchQueryDaily = pgTable(
  "search_query_daily",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    provider: text("provider").$type<SearchProvider>().notNull(),
    day: day(),
    query: text("query").notNull(),
    path: text("path").notNull(),
    impressions: integer("impressions").notNull(),
    clicks: integer("clicks").notNull(),
    /** The provider's average position (1 is the top); null when it gives none. */
    position: numeric("position", { precision: 6, scale: 2 }),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.provider, t.day, t.query, t.path] }),
    siteFk("search_query_daily_site_fk", t),
    check("search_query_daily_provider", oneOf(t.provider, SEARCH_PROVIDERS)),
    pathCheck("search_query_daily_path", t.path),
    check("search_query_daily_query", sql`length(${t.query}) between 1 and 512`),
    searchCounts("search_query_daily_counts", t),
    index("search_query_daily_tenant_idx").on(t.tenantId, t.siteId, t.provider, t.day),
  ],
);

/** A day's search figures by page (all queries, including those the provider withholds). */
export const searchPageDaily = pgTable(
  "search_page_daily",
  {
    tenantId: tenantId(),
    siteId: siteId(),
    provider: text("provider").$type<SearchProvider>().notNull(),
    day: day(),
    path: text("path").notNull(),
    impressions: integer("impressions").notNull(),
    clicks: integer("clicks").notNull(),
    position: numeric("position", { precision: 6, scale: 2 }),
  },
  (t) => [
    primaryKey({ columns: [t.siteId, t.provider, t.day, t.path] }),
    siteFk("search_page_daily_site_fk", t),
    check("search_page_daily_provider", oneOf(t.provider, SEARCH_PROVIDERS)),
    pathCheck("search_page_daily_path", t.path),
    searchCounts("search_page_daily_counts", t),
    index("search_page_daily_tenant_idx").on(t.tenantId, t.siteId, t.provider, t.day),
  ],
);

/**
 * A page of a client's site the area writes (a guide). Its path never changes (a moved page is a
 * new page and a redirect); only its status and live version do (trigger, 0038).
 */
export const contentPage = pgTable(
  "content_page",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    siteId: siteId(),
    path: text("path").notNull(),
    kind: text("kind").$type<ContentKind>().notNull().default("guide"),
    status: text("status").$type<ContentStatus>().notNull().default("draft"),
    /**
     * The version visitors see while published (the last one published after that).
     * DECISION: a one-column foreign key, as agent.live_version_id is, so the purge can clear it
     * and delete the page and its versions (a composite key would make them a cycle); that it is
     * one of this page's own versions, of the same client, is checked by a trigger (0038).
     */
    liveVersionId: uuid("live_version_id").references((): AnyPgColumn => contentVersion.id),
    createdByUserId: uuid("created_by_user_id").references(() => appUser.id),
    createdByAgentVersionId: uuid("created_by_agent_version_id"),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t): PgTableExtraConfigValue[] => [
    unique("content_page_id_tenant_key").on(t.id, t.tenantId),
    unique("content_page_path_key").on(t.tenantId, t.siteId, t.path),
    siteFk("content_page_site_fk", t),
    foreignKey({
      name: "content_page_agent_version_fk",
      columns: [t.createdByAgentVersionId, t.tenantId],
      foreignColumns: [agentVersion.id, agentVersion.tenantId],
    }),
    check("content_page_kind", oneOf(t.kind, CONTENT_KINDS)),
    check("content_page_status", oneOf(t.status, CONTENT_STATUSES)),
    pathCheck("content_page_path", t.path),
    check(
      "content_page_created_by",
      sql`num_nonnulls(${t.createdByUserId}, ${t.createdByAgentVersionId}) = 1`,
    ),
    check("content_page_live", sql`${t.status} <> 'published' or ${t.liveVersionId} is not null`),
  ],
);

/** One version of a page: never changed (trigger, 0038); an edit is a new version. */
export const contentVersion = pgTable(
  "content_version",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    pageId: uuid("page_id").notNull(),
    version: integer("version").notNull(),
    title: text("title").notNull(),
    description: text("description").notNull(),
    bodyMd: text("body_md").notNull(),
    targetQueries: text("target_queries").array().notNull().default(sql`'{}'::text[]`),
    authorUserId: uuid("author_user_id").references(() => appUser.id),
    authorAgentVersionId: uuid("author_agent_version_id"),
    runId: uuid("run_id"),
    /** Why this version: a person's note, or the agent's reason with its evidence. */
    why: text("why"),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t): PgTableExtraConfigValue[] => [
    unique("content_version_id_tenant_key").on(t.id, t.tenantId),
    unique("content_version_id_page_tenant_key").on(t.id, t.pageId, t.tenantId),
    unique("content_version_page_version_key").on(t.pageId, t.version),
    foreignKey({
      name: "content_version_page_fk",
      columns: [t.pageId, t.tenantId],
      foreignColumns: [contentPage.id, contentPage.tenantId],
    }),
    foreignKey({
      name: "content_version_agent_version_fk",
      columns: [t.authorAgentVersionId, t.tenantId],
      foreignColumns: [agentVersion.id, agentVersion.tenantId],
    }),
    runFk("content_version_run_fk", t),
    check("content_version_version", sql`${t.version} >= 1`),
    check(
      "content_version_author",
      sql`num_nonnulls(${t.authorUserId}, ${t.authorAgentVersionId}) = 1`,
    ),
    check(
      "content_version_sizes",
      sql`length(${t.title}) <= 200 and length(${t.description}) <= 500
        and length(${t.bodyMd}) <= 200000 and cardinality(${t.targetQueries}) <= 20`,
    ),
  ],
);

/** Each time a page went live or came down, and who signed it. Insert only (trigger, 0038). */
export const contentPublish = pgTable(
  "content_publish",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    pageId: uuid("page_id").notNull(),
    versionId: uuid("version_id").notNull(),
    action: text("action").$type<PublishAction>().notNull(),
    /** The `site.publish` action it went through; null only when nothing outside was written. */
    externalActionId: uuid("external_action_id"),
    byUserId: uuid("by_user_id")
      .notNull()
      .references(() => appUser.id),
    at: ts("at").notNull().defaultNow(),
  },
  (t) => [
    foreignKey({
      name: "content_publish_page_fk",
      columns: [t.pageId, t.tenantId],
      foreignColumns: [contentPage.id, contentPage.tenantId],
    }),
    foreignKey({
      name: "content_publish_version_fk",
      columns: [t.versionId, t.pageId, t.tenantId],
      foreignColumns: [contentVersion.id, contentVersion.pageId, contentVersion.tenantId],
    }),
    foreignKey({
      name: "content_publish_external_action_fk",
      columns: [t.externalActionId, t.tenantId],
      foreignColumns: [externalAction.id, externalAction.tenantId],
    }),
    check("content_publish_action", oneOf(t.action, PUBLISH_ACTIONS)),
    index("content_publish_page_idx").on(t.tenantId, t.pageId, t.at),
  ],
);

/** An old path that now answers with a redirect to another (a moved or retired page). */
export const contentRedirect = pgTable(
  "content_redirect",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    siteId: siteId(),
    fromPath: text("from_path").notNull(),
    toPath: text("to_path").notNull(),
    createdByUserId: uuid("created_by_user_id").references(() => appUser.id),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [
    unique("content_redirect_from_key").on(t.tenantId, t.siteId, t.fromPath),
    siteFk("content_redirect_site_fk", t),
    pathCheck("content_redirect_from_path", t.fromPath),
    pathCheck("content_redirect_to_path", t.toPath),
    check("content_redirect_not_self", sql`${t.fromPath} <> ${t.toPath}`),
  ],
);

/**
 * A version of the client's claims list: what its public text may and may never say. Insert only
 * (trigger, 0038); the newest version is the one the checks use. `created_by_user_id` is null
 * only for a list the pack installed.
 */
export const claimsVersion = pgTable(
  "claims_version",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    version: integer("version").notNull(),
    body: jsonb("body").notNull(),
    createdByUserId: uuid("created_by_user_id").references(() => appUser.id),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [
    unique("claims_version_id_tenant_key").on(t.id, t.tenantId),
    unique("claims_version_version_key").on(t.tenantId, t.version),
    check("claims_version_version", sql`${t.version} >= 1`),
    check("claims_version_body", sql`jsonb_typeof(${t.body}) = 'object'`),
  ],
);

/**
 * A report an agent wrote (the weekly site report). Its body and sources never change; only who
 * read it and when (trigger, 0038). Every number in it came from the figures in `sources`.
 */
export const marketingReport = pgTable(
  "marketing_report",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    siteId: siteId(),
    kind: text("kind").$type<ReportKind>().notNull(),
    periodFrom: date("period_from").notNull(),
    periodTo: date("period_to").notNull(),
    body: jsonb("body").notNull(),
    sources: jsonb("sources").notNull(),
    agentVersionId: uuid("agent_version_id").notNull(),
    runId: uuid("run_id"),
    createdAt: ts("created_at").notNull().defaultNow(),
    readAt: ts("read_at"),
    readByUserId: uuid("read_by_user_id").references(() => appUser.id),
  },
  (t) => [
    unique("marketing_report_id_tenant_key").on(t.id, t.tenantId),
    siteFk("marketing_report_site_fk", t),
    agentVersionFk("marketing_report_agent_version_fk", t),
    runFk("marketing_report_run_fk", t),
    check("marketing_report_kind", oneOf(t.kind, REPORT_KINDS)),
    check("marketing_report_period", sql`${t.periodFrom} <= ${t.periodTo}`),
    check("marketing_report_body", sql`jsonb_typeof(${t.body}) = 'object'`),
    check(
      "marketing_report_sources",
      sql`jsonb_typeof(${t.sources}) = 'array' and jsonb_array_length(${t.sources}) > 0`,
    ),
    check("marketing_report_read", sql`(${t.readAt} is null) = (${t.readByUserId} is null)`),
    index("marketing_report_tenant_idx").on(t.tenantId, t.siteId, t.periodTo),
  ],
);

/** A report's suggested action, decided by a person: Done or Not now. */
export const marketingReportAction = pgTable(
  "marketing_report_action",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    reportId: uuid("report_id").notNull(),
    idx: integer("idx").notNull(),
    text: text("text").notNull(),
    decision: text("decision").$type<ReportActionDecision>().notNull().default("open"),
    decidedByUserId: uuid("decided_by_user_id").references(() => appUser.id),
    decidedAt: ts("decided_at"),
  },
  (t) => [
    unique("marketing_report_action_idx_key").on(t.reportId, t.idx),
    foreignKey({
      name: "marketing_report_action_report_fk",
      columns: [t.reportId, t.tenantId],
      foreignColumns: [marketingReport.id, marketingReport.tenantId],
    }),
    check("marketing_report_action_decision", oneOf(t.decision, REPORT_ACTION_DECISIONS)),
    check("marketing_report_action_idx", sql`${t.idx} between 0 and 19`),
    check("marketing_report_action_text", sql`length(${t.text}) between 1 and 1000`),
    check(
      "marketing_report_action_decided",
      sql`(${t.decision} = 'open') = (${t.decidedAt} is null)
        and (${t.decidedAt} is null) = (${t.decidedByUserId} is null)`,
    ),
  ],
);

/**
 * A forum thread the forum watch looked at, once per client, source and id: seen by an agent, or
 * pasted by a person. Its title is the forum's text: data, never instructions (invariant 9).
 */
export const forumThread = pgTable(
  "forum_thread",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    source: text("source").$type<ForumSource>().notNull(),
    externalId: text("external_id").notNull(),
    url: text("url").notNull(),
    title: text("title").notNull(),
    seenAt: ts("seen_at").notNull().defaultNow(),
    /** Null until the watch has decided: a reply drafted, or passed over. */
    outcome: text("outcome").$type<ForumOutcome>(),
    agentVersionId: uuid("agent_version_id"),
    runId: uuid("run_id"),
    addedByUserId: uuid("added_by_user_id").references(() => appUser.id),
  },
  (t) => [
    unique("forum_thread_id_tenant_key").on(t.id, t.tenantId),
    unique("forum_thread_external_key").on(t.tenantId, t.source, t.externalId),
    agentVersionFk("forum_thread_agent_version_fk", t),
    runFk("forum_thread_run_fk", t),
    check("forum_thread_source", oneOf(t.source, FORUM_SOURCES)),
    check("forum_thread_outcome", sql`${t.outcome} is null or ${oneOf(t.outcome, FORUM_OUTCOMES)}`),
    check("forum_thread_seen_by", sql`num_nonnulls(${t.agentVersionId}, ${t.addedByUserId}) = 1`),
    check("forum_thread_url", sql`${t.url} ~ '^https://' and length(${t.url}) <= 2048`),
    check(
      "forum_thread_sizes",
      sql`length(${t.externalId}) between 1 and 512 and length(${t.title}) <= 500`,
    ),
  ],
);

/**
 * A reply an agent drafted for a named person to post by hand; agents never post
 * (docs/marketing-plan.md §4.6). The body never changes; its status and who decided do
 * (trigger, 0038).
 */
export const forumReply = pgTable(
  "forum_reply",
  {
    id: uuid("id").primaryKey().default(sql`uuid_generate_v7()`),
    tenantId: tenantId(),
    threadId: uuid("thread_id").notNull(),
    agentVersionId: uuid("agent_version_id").notNull(),
    runId: uuid("run_id"),
    body: text("body").notNull(),
    status: text("status").$type<ForumReplyStatus>().notNull().default("waiting"),
    /** The person who would post it, under their own name. */
    posterUserId: uuid("poster_user_id").references(() => appUser.id),
    decidedByUserId: uuid("decided_by_user_id").references(() => appUser.id),
    decidedAt: ts("decided_at"),
    postedAt: ts("posted_at"),
    /** A person's reason (rejected), in their words. */
    reason: text("reason"),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [
    unique("forum_reply_id_tenant_key").on(t.id, t.tenantId),
    foreignKey({
      name: "forum_reply_thread_fk",
      columns: [t.threadId, t.tenantId],
      foreignColumns: [forumThread.id, forumThread.tenantId],
    }),
    agentVersionFk("forum_reply_agent_version_fk", t),
    runFk("forum_reply_run_fk", t),
    check("forum_reply_status", oneOf(t.status, FORUM_REPLY_STATUSES)),
    check("forum_reply_body", sql`length(${t.body}) between 1 and 10000`),
    check(
      "forum_reply_decided",
      sql`(${t.status} = 'waiting') = (${t.decidedAt} is null)
        and (${t.decidedAt} is null) = (${t.decidedByUserId} is null)`,
    ),
    check("forum_reply_posted", sql`(${t.status} = 'posted') = (${t.postedAt} is not null)`),
    index("forum_reply_tenant_idx").on(t.tenantId, t.status, t.createdAt),
  ],
);

/** The pack's tables, for the migration's RLS block and the pack's schema test. */
export const MARKETING_TABLES = [
  "site",
  "site_salt",
  "site_event",
  "site_visit",
  "site_daily_page",
  "site_daily_click",
  "site_daily_total",
  "site_bot_daily",
  // 0038
  "search_source",
  "search_query_daily",
  "search_page_daily",
  "content_page",
  "content_version",
  "content_publish",
  "content_redirect",
  "claims_version",
  "marketing_report",
  "marketing_report_action",
  "forum_thread",
  "forum_reply",
] as const;
export type MarketingTable = (typeof MARKETING_TABLES)[number];

/**
 * Tables whose rows are never deleted and never changed but for the columns named
 * (`forbid_update_except` triggers, 0038); [] is insert only.
 */
export const MARKETING_IMMUTABLE: Partial<Record<MarketingTable, readonly string[]>> = {
  content_page: ["status", "live_version_id"],
  content_version: [],
  content_publish: [],
  claims_version: [],
  marketing_report: ["read_at", "read_by_user_id"],
  marketing_report_action: ["decision", "decided_by_user_id", "decided_at"],
  forum_reply: [
    "status",
    "poster_user_id",
    "decided_by_user_id",
    "decided_at",
    "posted_at",
    "reason",
  ],
};
